<script lang="ts">
 import {onMount} from 'svelte';import {invalidateAll} from '$app/navigation';import {Clock,ArrowRightLeft,Pause,Play,WifiOff} from 'lucide-svelte';
 import {clockContext,queueKey,type PayrollWorkspace,type PendingPunch} from '$lib/payroll';
 let {workspace:w,tenant}:{workspace:PayrollWorkspace;tenant:string}=$props();
 let ready=$state(false),online=$state(true),busy=$state(false),message=$state(''),job=$state(''),costCode=$state(''),classification=$state(''),notes=$state(''),breakKind=$state('UNPAID');let queue=$state<PendingPunch[]>([]);
 const active=$derived(w.time.find(t=>t.employeeId===w.employeeId&&t.status==='ACTIVE'));const onBreak=$derived(active?.breaks?.some(b=>!b.end));const key=$derived(queueKey(tenant,w.employeeId));
 onMount(()=>{ready=true;online=navigator.onLine;costCode=w.configuration.costCodes[0]||'';classification=w.configuration.classifications[0]||'';job=w.schedule.find(e=>e.jobId)?.jobId||'';try{queue=JSON.parse(localStorage.getItem(key)||'[]');}catch{message='Saved punch queue could not be read. Contact payroll before entering replacement time.';}const update=()=>{online=navigator.onLine;};window.addEventListener('online',update);window.addEventListener('offline',update);return()=>{window.removeEventListener('online',update);window.removeEventListener('offline',update);};});
 function persist(){localStorage.setItem(key,JSON.stringify(queue));}
 async function sync(){if(!online||busy)return;busy=true;try{for(let i=0;i<queue.length;i++){const item=queue[i];if(item.state==='conflict')break;const res=await fetch(`/${tenant}/admin/payroll/punch`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item.command)});const result=await res.json();if(!res.ok){queue[i]={...item,state:'conflict',message:result.message||'Server conflict. Review recorded time with payroll.'};persist();break;}queue=queue.filter((_,index)=>index!==i);i--;persist();}await invalidateAll();message=queue.length?'Pending sync: a conflict requires review.':'All queued punches are server-confirmed.';}catch{message='Pending sync. Connection failed; punches remain on this device.';}finally{busy=false;}}
 async function clockLocation():Promise<{latitude:number;longitude:number;accuracy:number;evidence:string}|null>{if(w.configuration.locationPolicy==='OFF')return null;try{const point=await new Promise<GeolocationPosition>((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:false,timeout:7000,maximumAge:0}));return {latitude:point.coords.latitude,longitude:point.coords.longitude,accuracy:point.coords.accuracy,evidence:'Browser geolocation at employee punch'};}catch{return null;}}
 async function punch(action:string){if(busy||!ready)return;busy=true;message='';const context=clockContext(w,{jobId:job||null,costCode,classification,notes});const command={id:crypto.randomUUID(),expectedVersion:w.version,action,targetId:active?.id||'00000000-0000-0000-0000-000000000000',at:new Date().toISOString(),reason:notes||'Employee clock action',time:['clock-in','switch'].includes(action)?context:null,breakKind};
 try{if(['clock-in','switch'].includes(action)&&w.configuration.locationPolicy!=='OFF'){const location=await clockLocation();if(!location&&w.configuration.locationPolicy==='REQUIRE_WITH_OVERRIDE'&&!notes.trim()){message='Location unavailable. Add an explicit override note before clocking time.';return;}Object.assign(context,{location});}if(!online){queue=[...queue,{tenant,employeeId:w.employeeId,command,state:'pending'}];persist();message='Pending sync. This punch is saved on this device and is not server-confirmed.';return;}const response=await fetch(`/${tenant}/admin/payroll/punch`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(command)});const result=await response.json();if(!response.ok){message=result.message||'Clock action was not confirmed. Refresh and review.';return;}message='Clock action confirmed.';await invalidateAll();}catch{queue=[...queue,{tenant,employeeId:w.employeeId,command,state:'pending'}];try{persist();message='Pending sync. Outcome unconfirmed; retry uses the same punch identity.';}catch{message='Punch could not be saved. Keep the time and contact payroll.';}}finally{busy=false;}}
</script>
<section class="clock" aria-labelledby="clock-title"><div class="eyebrow"><Clock size={18} aria-hidden="true"/> MY TIME</div><h2 id="clock-title">{active?w.jobs.find(j=>j.id===active.jobId)?.name||'General work':'Ready for your day?'}</h2><p class="clock-status">{active?`${onBreak?'On break':'Clocked in'} · ${new Date(active.clockIn!).toLocaleTimeString([],{hour:'numeric',minute:'2-digit',timeZone:active.timezone})}`:'Clocked out'}</p>{#if active}<p>Current task · {active.costCode}</p>{/if}
 {#if w.configuration.jobsEnabled&&w.configuration.integrateJobs!==false}<label>Job<select bind:value={job}><option value="">General / non-job work</option>{#each w.jobs as j}<option value={j.id}>{j.name}</option>{/each}</select></label>{/if}
 <div class="context"><label>Task / cost code<select bind:value={costCode}>{#each w.configuration.costCodes as code}<option>{code}</option>{/each}</select></label><label>Labor classification<select bind:value={classification}>{#each w.configuration.classifications as value}<option>{value}</option>{/each}</select></label></div>
 <label>Note or issue<input bind:value={notes} maxlength="2000" placeholder="Optional note"/></label>
 {#if !online}<p role="status"><WifiOff size={16} aria-hidden="true"/> Offline. Saved punches will show Pending sync.</p>{/if}
 {#if w.configuration.enabled&&w.grants['time.self']}<button class="primary" disabled={!ready||busy||queue.length>0||onBreak} onclick={()=>punch(active?'clock-out':'clock-in')}>{active?'Clock Out':'Clock In'}</button>{#if active}<label>Break type<select bind:value={breakKind}><option value="UNPAID">Unpaid break</option><option value="MEAL">Meal break</option><option value="PAID">Paid break</option></select></label><div class="secondary"><button disabled={!ready||busy||queue.length>0} onclick={()=>punch(onBreak?'end-break':'start-break')}>{#if onBreak}<Play size={16} aria-hidden="true"/>End break{:else}<Pause size={16} aria-hidden="true"/>Start break{/if}</button><button disabled={!ready||busy||queue.length>0||onBreak} onclick={()=>punch('switch')}><ArrowRightLeft size={16} aria-hidden="true"/>Switch Job / task</button></div>{/if}{/if}
 {#if message}<p role="status" aria-live="polite">{message}</p>{/if}
 {#if queue.length}<div class="pending"><h3>Pending sync · {queue.length} punch{queue.length===1?'':'es'}</h3>{#each queue as item}<p>{item.command.action as string} · {item.command.at as string} · {item.state}{item.message?` · ${item.message}`:''}</p>{/each}<button disabled={!online||busy||queue.some(q=>q.state==='conflict')} onclick={sync}>Sync saved punches</button><p>Conflicts remain saved. Refresh and ask payroll to review the original timestamp before recording a correction.</p></div>{/if}
</section>
<style>
.clock{max-width:42rem;padding:1.5rem;border:1px solid var(--border,#cbd5e1);border-top:4px solid #0f766e;border-radius:1rem;background:var(--surface,#fff);color:var(--text-strong,#172e32)}.eyebrow{display:flex;gap:.5rem;align-items:center;color:#0f766e;font-size:.8rem;font-weight:700;letter-spacing:.12em}h2{font-size:1.9rem;line-height:1.2;margin:.75rem 0}.clock-status{font-size:1.2rem;font-weight:600}.context,.secondary{display:flex;gap:.75rem;flex-wrap:wrap}label{display:flex;flex:1;flex-direction:column;gap:.4rem;margin:.8rem 0;font-size:.9rem}input,select{width:100%;min-height:46px;padding:.6rem;border:1px solid #64748b;border-radius:.5rem;background:var(--surface,#fff);color:inherit}button{display:inline-flex;gap:.5rem;align-items:center;justify-content:center;min-height:48px;padding:.75rem 1rem;border:1px solid #64748b;border-radius:.6rem;color:inherit;background:transparent;cursor:pointer}.primary{width:100%;font-size:1.15rem;font-weight:700;background:#c2410c;border-color:#c2410c;color:#fff;margin:.8rem 0}.pending{border-left:3px solid #c2410c;padding-left:1rem}button:disabled{opacity:.55;cursor:not-allowed}:is(button,input,select):focus-visible{outline:3px solid #0d9488;outline-offset:3px}:global(.dark) .clock,:global([data-theme='dark']) .clock{background:#12282d;color:#e2e8f0}:global(.dark) input,:global(.dark) select,:global([data-theme='dark']) input,:global([data-theme='dark']) select{background:#12282d;color:#e2e8f0}:global(.dark) .eyebrow,:global([data-theme='dark']) .eyebrow{color:#5eead4}
</style>
